# Offline emulation of the Windows PowerShell/pwsh alias table that Linux pwsh lacks (cp, ls, mv, rm, cat, diff, sort, kill, ps, echo, type, sleep, copy, del, dir, move, ren, md, rd, rmdir, cd, pwd, clear, curl, wget, man, r, h, history, gc, gi, gl, gm, gp, gu, gv, sc, si, sl, sp, sv, ft, fl, fw, ii, iex, kill, ogv, oh, where, select, group, measure, compare, tee, write). An alias outranks a function of the same name, exactly as on the Windows runner.
$map=@{ cp='Copy-Item'; copy='Copy-Item'; cpi='Copy-Item'; ls='Get-ChildItem'; dir='Get-ChildItem'; gci='Get-ChildItem'; mv='Move-Item'; move='Move-Item'; mi='Move-Item'; rm='Remove-Item'; del='Remove-Item'; erase='Remove-Item'; rd='Remove-Item'; rmdir='Remove-Item'; ri='Remove-Item'; cat='Get-Content'; type='Get-Content'; gc='Get-Content'; diff='Compare-Object'; compare='Compare-Object'; sort='Sort-Object'; kill='Stop-Process'; ps='Get-Process'; gps='Get-Process'; echo='Write-Output'; write='Write-Output'; sleep='Start-Sleep'; ren='Rename-Item'; rni='Rename-Item'; cd='Set-Location'; sl='Set-Location'; chdir='Set-Location'; pwd='Get-Location'; gl='Get-Location'; clear='Clear-Host'; curl='Invoke-WebRequest'; wget='Invoke-WebRequest'; iwr='Invoke-WebRequest'; irm='Invoke-RestMethod'; man='Get-Help'; r='Invoke-History'; h='Get-History'; history='Get-History'; gi='Get-Item'; gm='Get-Member'; gp='Get-ItemProperty'; sp='Set-ItemProperty'; sc='Set-Content'; ac='Add-Content'; si='Set-Item'; gv='Get-Variable'; sv='Set-Variable'; set='Set-Variable'; ft='Format-Table'; fl='Format-List'; fw='Format-Wide'; ii='Invoke-Item'; iex='Invoke-Expression'; ogv='Out-GridView'; oh='Out-Host'; where='Where-Object'; select='Select-Object'; group='Group-Object'; measure='Measure-Object'; tee='Tee-Object'; foreach='ForEach-Object'; gcm='Get-Command'; gal='Get-Alias'; nal='New-Alias'; sal='Set-Alias'; ni='New-Item'; md='mkdir'; mp='Move-ItemProperty'; clc='Clear-Content'; cli='Clear-Item'; clv='Clear-Variable'; gsv='Get-Service'; gu='Get-Unique'; icm='Invoke-Command'; sls='Select-String'; start='Start-Process'; saps='Start-Process'; gwmi='Get-WmiObject' }
$n=0; foreach($k in $map.Keys){ if(Get-Command $map[$k] -ErrorAction SilentlyContinue){ Set-Alias -Name $k -Value $map[$k] -Scope Global -Option AllScope -Force -ErrorAction SilentlyContinue; $n++ } }
Write-Output "WINALIAS emulated aliases defined: $n (cp -> $((Get-Alias cp).Definition))"
